    d={'I3':(I3,"A","current in the shared resistor"),'V3':(Vn,"V","voltage across the shared resistor"),'I1':(I1,"A","current in the left battery"),'P3':(I3**2*R3,"W","power dissipated in the shared resistor")}[ask]
    q=f"Two batteries share a middle resistor. Left branch: {E1} V with {R1} Ω. Right branch: {E2} V with {R2} Ω. Shared resistor: {R3} Ω. Find the {d[2]}."
    num(K,l,b,q,d[0],d[1],"Use KCL at the top node and KVL on two loops (or node voltage).",[f"I₃ = I₁ + I₂; {E1} = {R1}I₁ + {R3}I₃; {E2} = {R2}I₂ + {R3}I₃.",f"Solving: I₁ = {g(I1)} A, I₂ = {g(I2)} A, I₃ = {g(I3)} A.",f"Shared-resistor voltage = {g(Vn)} V. Check: supplied power equals dissipated power."])
