num(K,3,1.4,"A 12 V battery (1 Ω internal) and a 6 V battery (1 Ω internal) are in parallel across a 2 Ω load. Find the current through the 6 V battery, magnitude in amps. (It may be charging.)",abs(6-V0)/1,"A","Find the common node voltage first.",[f"Node voltage = (12/1 + 6/1)/(1 + 1 + 1/2) = {g(V0)} V.",f"Current in 6 V cell = (6 − {g(V0)})/1 = {g(6-V0)} A.",f"Negative: current flows into the 6 V cell, charging it at {g(abs(6-V0))} A."])
E=[(0,1,2),(1,2,4),(0,3,6),(3,2,3),(1,3,6)]
# bridge by KVL: unbalanced
Vn=nodal([(0,1,100),(1,2,200),(0,3,300),(3,2,100),(1,3,100)],4,{0:12,2:0})
num(K,3,1.5,"V_P and V_Q are the midpoints of two dividers across 12 V. P: 100 Ω above, 200 Ω below. Q: 300 Ω above, 100 Ω below. No link between them. What is the voltage V_P − V_Q? Give volts.",12*200/300-12*100/400,"V","Treat each divider alone (no link, so no loading).",["V_P = 12 × 200/300 = 8 V.","V_Q = 12 × 100/400 = 3 V.","V_P − V_Q = 5 V."],tol=0.02)
# Millman node
Vm=(10/2+4/1+0/4)/(1/2+1+1/4)
num(K,3,1.5,"Three branches join at a top node and return to a common bottom node. Branch 1: 10 V source with 2 Ω. Branch 2: 4 V source with 1 Ω. Branch 3: just 4 Ω (no source). Find the voltage across the 4 Ω resistor. Give volts.",Vm,"V","KCL at the top node with branch currents (E − V)/R: the three currents out of the node (V/R) must balance.",[f"(10 − V)/2 + (4 − V)/1 = V/4.",f"5 + 4 = V(0.5 + 1 + 0.25).",f"V = 9/1.75 = {g(Vm)} V."])
num(K,3,1.4,"A circuit has 6 branches and 4 nodes. How many INDEPENDENT KVL loop equations are needed (with KCL used at 3 of the nodes)?",3,"","Independent loops = branches − nodes + 1.",["Independent KCL equations = nodes − 1 = 3.","Unknown currents = 6, so need 6 equations in all.","KVL loops needed = 6 − 3 = 3."])
mcq(K,3,1.0,"In a network, you find power supplied by sources = 40 W but power in the resistors = 45 W. What should you conclude?","There is an error: power must balance",["The wire resistance supplies the extra","The network has gained energy","This is normal for parallel branches"],"Energy is conserved, so supplied power equals dissipated power.",["Σ P(supplied) = Σ P(dissipated).","A mismatch means an arithmetic or sign mistake.","Recheck the KVL signs."])
I1,I2,I3,Vn=solve2(10,1,4,2,2)
num(K,3,1.2,"Two batteries: E₁ = 10 V (1 Ω) and E₂ = 4 V (2 Ω) in parallel with a 2 Ω load. How much power does the 10 V battery's source supply (E₁ × I₁)? Give watts.",10*I1,"W","Find I₁ from the node voltage.",[f"V = (10/1 + 4/2)/(1 + 1/2 + 1/2) = {g(Vn)} V.",f"I₁ = (10 − {g(Vn)})/1 = {g(I1)} A.",f"P = 10 × {g(I1)} = {g(10*I1)} W."])
# KVL path independence
num(K,3,1.0,"In a loop circuit, going from point A to B by the top path you pass a 6 V rise then a 2 V drop. By KVL, how many volts is V_AB when you go by the bottom path, which has a single 4 V drop? (rise positive)",4,"V","Potential difference between two points is the same by any path.",["Top path: +6 − 2 = +4 V.","Bottom path must match: change of +4 V.","So the bottom path element is a 4 V rise in the direction A to B."]) if False else None
mcq(K,3,1.1,"Going from A to B along the top path you meet a 6 V rise then a 2 V drop. Along the bottom path you meet one element. For KVL to hold, that element's change from A to B is:","a 4 V rise",["a 4 V drop","a 8 V rise","a 2 V drop"],"The net change A to B is the same on every path: +6 − 2 = +4 V.",["Top path: +6 then −2 gives +4.","Voltage is path-independent in these circuits.","Bottom must also give +4 V."])
mcq(K,3,1.3,"A loop has a 12 V battery and resistors R1 and R2 in series. A student writes 12 − IR1 + IR2 = 0. The error is:","IR2 should be a drop (−IR2), since current flows through it the same way",["The battery should be negative","KVL should sum to the battery voltage, not zero","There is no error"],"Both resistors are drops going with the current: 12 − IR1 − IR2 = 0.",["Same current direction through both.","Both are voltage drops.","Correct: 12 − IR1 − IR2 = 0."])
num(K,3,1.0,"Four wires meet at a junction: A brings in 3 A, B takes out 8 A, C brings in 2 A. The unknown wire D carries current INTO the junction. How many amps?",3,"A","In = out: 3 + 2 + I_D = 8.",["Currents in: 3 + 2 + D.","Currents out: 8.","D = 3 A."])
num(K,3,1.7,"A 12 V battery sends current to a node. From there 3 Ω (to ground) is in parallel with a path of 2 Ω in series with 4 Ω (to ground). Find the current in the 4 Ω resistor. Give amps.",12/par(3,6)*0+ (12/( (par(3,6)) ))*(1/ (1+0)) *0+ (12/ (par(3,6)+0))*0+ (par(3,6)/6)*0 + 0,"A","tmp",["x"]) if False else None
# deeper two-node with KCL: second battery reversed
V1=(12/2 - 6/1)/(1/2+1+1/3)
num(K,3,1.9,"Left: 12 V with 2 Ω. Right: a 6 V battery wired in opposition (its + end toward the shared node's negative side) with 1 Ω. Shared: 3 Ω. Take the top node voltage with the left battery + up and the right battery + down. Find the voltage across the 3 Ω resistor in volts.",abs(V1),"V","Node equation: (12 − V)/2 + (−6 − V)/1 = V/3.",["Right branch behaves like a −6 V source.","6 − V/2 + (−6) − V = V/3 gives 0 = V(1/2 + 1 + 1/3).",f"V = {g(V1)} V (right at 0 since 12/2 − 6 = 0, check: 6 − 6 = 0)."]) if False else None
V1=(12/2 + (-6)/1)/(1/2+1+1/3)
num(K,3,1.9,"A 12 V battery (2 Ω) and a 6 V battery (1 Ω) face each other: the 6 V battery is connected with its terminals reversed relative to the 12 V one, across a shared 3 Ω resistor. Find the voltage across the 3 Ω resistor. Give volts (magnitude).",abs(V1),"V","Treat the reversed battery as a −6 V source at the common node.",[f"(12 − V)/2 + (−6 − V)/1 = V/3.","6 − V/2 − 6 − V = V/3, so V(1/2 + 1 + 1/3) = 0.","V = 0: the two branches exactly cancel, so no current flows in the 3 Ω."])
